        k = "video-heavy" if mv >= 50 else "too few posts"
    elif not why:
        k = "no log line"; st = mv = None
    else:
        k = "other: " + why[:60]; st = mv = None
    kinds[k.split(":")[0]] += 1
    rows.append({"sub": r["sub"], "heading": r["heading"], "tier": r["tier_name"], "lane": r["lane"], "kind": k, "still": st, "moving": mv, "why": why[:160]})
