import glob, json, re, collections, os
R = r"C:\Users\U01_LEECHSEED\Desktop\_setsunadev\_PRIVATE\reference"
q = json.load(open(os.path.join(R, "pullqueue", "queue.json"), encoding="utf-8"))["boards"]
empty = {r["sub"].lower(): r for r in q if r["status"] == "empty"}
last = {}
pat = re.compile(r"PULL: r/(\S+)\s+\S+\s+(.*)")
for f in sorted(glob.glob(os.path.join(R, "*.log"))):
    for ln in open(f, encoding="utf-8", errors="replace"):
        m = pat.search(ln)
        if m and m.group(1).lower() in empty:
            last[m.group(1).lower()] = m.group(2).strip()
kinds = collections.Counter()
rows = []
for s, r in empty.items():
    why = last.get(s, "")
    m = re.search(r"SKIPPED by recon: (\d+) still posts at 250\+ vs (\d+) moving", why)
    if m:
        st, mv = int(m.group(1)), int(m.group(2))
        k = "video-heavy" if mv >= 50 else "too few posts"
    elif not why:
        k = "no log line"; st = mv = None
    else:
        k = "other: " + why[:60]; st = mv = None
    kinds[k.split(":")[0]] += 1
    rows.append({"sub": r["sub"], "heading": r["heading"], "tier": r["tier_name"], "lane": r["lane"], "kind": k, "still": st, "moving": mv, "why": why[:160]})
print(kinds)
for k in ("other", "no log line"):
    print(k, [x["sub"] + " | " + x["why"][:90] for x in rows if x["kind"].startswith(k)][:8])
print("still>=20 and video-heavy:", sum(1 for x in rows if x["kind"] == "video-heavy" and (x["still"] or 0) >= 20))
json.dump(rows, open(os.path.join(R, "pullqueue", "empty-reasons.json"), "w", encoding="utf-8"), indent=1, ensure_ascii=False)

def run_wave(n):
    # one runner per wave: a second "wave N" while N is pulling would pull the same waiting boards twice
    lock = os.path.join(os.path.dirname(CHECK), f"wave{n}.lock")
    try:
        fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
    except FileExistsError:
        print(f"==== wave {n} already running ({lock}); delete the lock if that runner died", flush=True)
        return
    os.write(fd, str(os.getpid()).encode()); os.close(fd)
    try:
        _run_wave(n)
    finally:
        os.remove(lock)


def _dropped_now(sub):
    """The live drop list: boardmap.json "dropped" plus any board marked dropped in the queue (10/13)."""
    try:
        from drop_guard import RISK   # 10/17 (Chief: "drop it"): the wider filter, live in every wave
        if RISK.search(sub):
            return True
        bm = json.load(open(BOARDMAP, encoding="utf-8"))
        if sub.lower() in {k.lower() for k in bm.get("dropped", {})}:
            return True
        q = json.load(open(QUEUE, encoding="utf-8"))
        return any(x["sub"] == sub and x["status"] == "dropped" for x in q["boards"])
    except (OSError, ValueError):
        return False


def heal_dropped():
    """A wave started before a drop marks a skipped board "empty"; put it back to "dropped" (run by report)."""
    try:
        bm = {k.lower() for k in json.load(open(BOARDMAP, encoding="utf-8")).get("dropped", {})}
        q = json.load(open(QUEUE, encoding="utf-8"))
    except (OSError, ValueError):
        return 0
    n = 0
    for x in q["boards"]:
        if x["sub"].lower() in bm and x["status"] != "dropped":   # the pull and load guards keep its images out
            x["status"] = "dropped"; n += 1
    if n:
        save(q)
    return n


def _run_wave(n):
    q = json.load(open(QUEUE, encoding="utf-8"))
    todo = [r for r in q["boards"] if r["wave"] == n and r["status"] == "waiting"]
    if not todo:
        print(f"==== wave {n} · nothing waiting · {time.strftime('%H:%M')}", flush=True)
        return
    print(f"==== wave {n} · {len(todo)} boards · {time.strftime('%H:%M')}", flush=True)
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    first = True
    for r in todo:
        if _dropped_now(r["sub"]):   # 10/13: Chief can drop a board while its wave runs; skip it, no rest
            print(f"==== {r['sub']} skipped, dropped by Chief {time.strftime('%H:%M')}", flush=True)
            continue
        if not first:
            time.sleep(REST)
        first = False
        print(f"==== {r['sub']} ({r['lane']}) {time.strftime('%H:%M')}", flush=True)
        p = subprocess.run([PY, os.path.join(HERE, "ref_pull.py"), r["sub"], "--min-score", "250", "--limit", "300"],
                           capture_output=True, text=True, env=env, cwd=ROOT, creationflags=NOWIN)
        for l in p.stdout.splitlines():
            if l.startswith(("PULL: r/", "PULL: done")) or "Error" in l:
                print(l, flush=True)
        if p.returncode:   # 10/14: a failed pull was silent (stderr captured and dropped); log its last lines
            print(f"==== ERROR ref_pull exit {p.returncode}: " + " | ".join(p.stderr.strip().splitlines()[-5:]), flush=True)
        img = os.path.join(REF_ROOT, r["sub"], "img")
        count = len(os.listdir(img)) if os.path.isdir(img) else 0
        if count:
            lp = subprocess.run([PY, os.path.join(HERE, "ref_load.py"), os.path.join(REF_ROOT, r["sub"]),
                                 "--lane", "gay" if r["lane"] == "male" else "straight"],
                                capture_output=True, text=True, env=env, cwd=ROOT, creationflags=NOWIN)
            print("\n".join(l for l in lp.stdout.splitlines() if l.startswith("LOAD: ")), flush=True)
            if lp.returncode:
                print(f"==== ERROR ref_load exit {lp.returncode}: " + " | ".join(lp.stderr.strip().splitlines()[-5:]), flush=True)
        from xlock import xlock
        with xlock(QUEUE + ".lock"):   # 10/16: read-modify-write under one lock, so runners never save at once
            with open(QUEUE, encoding="utf-8") as fh:
                q = json.load(fh)           # re-read: the checklist may have been edited by hand
            for x in q["boards"]:
                if x["sub"] == r["sub"]:
                    x["status"], x["images"], x["pulled"] = ("done" if count else "empty"), count, time.strftime("%Y-%m-%d %H:%M")
            save(q)
    print(f"==== wave {n} done {time.strftime('%H:%M')}", flush=True)
    subprocess.run([sys.executable, os.path.join(HERE, "board_match.py")], cwd=HERE, env=env, creationflags=NOWIN)   # re-wires the rail itself
    subprocess.run([sys.executable, os.path.join(HERE, "board_glass.py")], cwd=HERE, env=env, creationflags=NOWIN)
    subprocess.run([sys.executable, os.path.join(HERE, "layers.py")], cwd=HERE, env=env, creationflags=NOWIN)


def status():
    q = json.load(open(QUEUE, encoding="utf-8"))
    waves = sorted({r["wave"] for r in q["boards"] if r["wave"]})
    for w in waves:
        wr = [r for r in q["boards"] if r["wave"] == w]
        print(f"wave {w}: {sum(r['status'] == 'done' for r in wr)}/{len(wr)} done · {sum(r['status'] == 'empty' for r in wr)} empty")

def wave_log(n):
    return os.path.join(os.path.dirname(QDIR), f"wave{n}.log")


def wave_busy(n):
    """A wave is taken while its lock exists, or while its log is live: written in the last 45 min with no done line
    (wave 1 began before the locks existed)."""
    if os.path.exists(os.path.join(QDIR, f"wave{n}.lock")):
        return True
    log = wave_log(n)
    if os.path.exists(log) and time.time() - os.path.getmtime(log) < 45 * 60:
        return f"==== wave {n} done" not in open(log, encoding="utf-8", errors="replace").read()
    return False


def chain(after=None):
    """Chief 10/12: "chain the waves". Each chain runner waits for wave `after` to land (if given), then keeps
    taking the lowest free wave until none is left. Each wave writes its own waveN.log. Touch pullqueue/STOP to end
    every chain after its current wave."""
    stop = os.path.join(QDIR, "STOP")
    if after:
        while f"==== wave {after} done" not in (open(wave_log(after), encoding="utf-8", errors="replace").read()
                                                if os.path.exists(wave_log(after)) else ""):
            time.sleep(120)
    real = sys.stdout
    while not os.path.exists(stop):
        q = json.load(open(QUEUE, encoding="utf-8"))
        free = sorted({r["wave"] for r in q["boards"] if r["wave"] and r["status"] == "waiting"})
        free = [n for n in free if not wave_busy(n)]
        if not free:
            break
        n = free[0]
        with open(wave_log(n), "a", encoding="utf-8") as log:
            sys.stdout = log
            try:
                run_wave(n)
            finally:
                sys.stdout = real
        time.sleep(5)
    print(f"chain ends {time.strftime('%H:%M')}: " + ("STOP file" if os.path.exists(stop) else "no free wave"), flush=True)

