1	// command: the Command's terminal front end (BOLO 153, Chief 10/18 "go": Go + the Charm kit).
2	//
3	//	command up      boot the whole architecture from a shell: VS Code on the repo, then the launch sequence
4	//	                (stations, JUDY, the Console as the viewer), drawn live as the boot screen with the
5	//	                spinning mark and the fetch panel; it holds on "press SPACE to continue"
6	//	command fetch   the mark and the fetch panel, printed once (neofetch for the Command)
7	//
8	// Python stays the engine: launch.py runs the stations and writes boot.jsonl; this program only draws it.
9	// Build: see build.cmd beside this file.
10	package main
11	
12	import (
13		"bufio"
14		"encoding/json"
15		"fmt"
16		"io"
17		"os"
18		"os/exec"
19		"path/filepath"
20		"strings"
21		"time"
22	
23		tea "github.com/charmbracelet/bubbletea"
24		"github.com/charmbracelet/lipgloss"
25		"github.com/charmbracelet/x/ansi"
26	)
27	
28	var root = `C:\Users\U01_LEECHSEED\Desktop\_setsunadev` // set at build time with -ldflags "-X main.root=..."
29	
30	func init() {
31		if r := os.Getenv("COMMAND_ROOT"); r != "" {
32			root = r
33		}
34	}
35	
36	type event struct {
37		T       float64  `json:"t"`
38		State   string   `json:"state"`
39		Station string   `json:"station"`
40		Go      bool     `json:"go"`
41		Note    string   `json:"note"`
42		Waves   []string `json:"waves"`
43		Sub     []string `json:"sub"`
44	}
45	
46	var early = [][2]string{
47		{":: running early hook", "[udev]"}, {":: running hook", "[keymap]"}, {":: mounting", "'/dev/q' on real root"},
48		{":: loading", "the Command · SOP · BOLO · STATE"}, {":: starting", "systemd-launch (BOLO 58)"},
49	}
50	
51	type tickMsg time.Time
52	type launchDone struct{ err error }
53	
54	type model struct {
55		w, h       int
56		start      time.Time
57		startEpoch float64
58		spin       *spinner
59		fetch      [][2]string
60		lines      []string // finished lines: the early hooks, then one per station (plus its sub lines)
61		earlyShown int
62		running    string
63		runSince   time.Time
64		frame      int
65		ok, bad    int
66		ended      bool
67		launchErr  error
68		events     string // path to boot.jsonl
69		offset     int64
70		partial    string
71		logPath    string
72	}
73	
74	func stamp(sec float64) string { return sDim.Render(fmt.Sprintf("[%8.3f]", sec)) }
75	
76	func pad(s string, n int) string {
77		if len(s) >= n {
78			return s
79		}
80		return s + strings.Repeat(" ", n-len(s))
81	}
82	
83	func stationLine(e event, sec float64) []string {
84		tag, verdict := sOK.Render("[  OK  ]"), sOK.Render("GO    ")
85		if !e.Go {
86			tag, verdict = sBad.Render("[FAILED]"), sBad.Render("NO-GO ")
87		}
88		note := e.Note
89		if len(e.Waves) > 0 {
90			note = fmt.Sprintf("%d waves open", len(e.Waves))
91		}
92		if len(note) > 52 {
93			note = note[:52]
94		}
95		out := []string{fmt.Sprintf("%s %s %s %s %s %s", stamp(sec), tag, sWhite.Render(pad(e.Station, 10)),
96			sDim.Render(strings.Repeat(".", 30)), verdict, sDim.Render(note))}
97		for _, s := range e.Sub {
98			out = append(out, "           "+sDim.Render("└─ "+trunc(s, 92)))
99		}
100		for _, wv := range e.Waves {
101			st := sOK
102			if strings.Contains(wv, "STALLED") {
103				st = sBad
104			}
105			out = append(out, "           "+sDim.Render("└─ ")+st.Render(trunc(wv, 90)))
106		}
107		return out
108	}
109	
110	func trunc(s string, n int) string {
111		r := []rune(s)
112		if len(r) > n {
113			return string(r[:n])
114		}
115		return s
116	}
117	
118	func tick() tea.Cmd {
119		return tea.Tick(50*time.Millisecond, func(t time.Time) tea.Msg { return tickMsg(t) })
120	}
121	
122	func (m *model) Init() tea.Cmd { return tick() }
123	
124	// readEvents takes the new whole lines of boot.jsonl; events older than this run are the last launch's, skipped
125	func (m *model) readEvents() {
126		f, err := os.Open(m.events)
127		if err != nil {
128			return
129		}
130		defer f.Close()
131		if st, err := f.Stat(); err == nil && st.Size() < m.offset {
132			m.offset, m.partial = 0, "" // the launch truncated the file: start over
133		}
134		f.Seek(m.offset, io.SeekStart)
135		b, _ := io.ReadAll(f)
136		m.offset += int64(len(b))
137		chunk := m.partial + string(b)
138		parts := strings.Split(chunk, "\n")
139		m.partial = parts[len(parts)-1]
140		for _, l := range parts[:len(parts)-1] {
141			var e event
142			if json.Unmarshal([]byte(strings.TrimSpace(l)), &e) != nil || e.T < m.startEpoch-2 {
143				continue
144			}
145			switch e.State {
146			case "start":
147				m.running, m.runSince = e.Station, time.Now()
148			case "done":
149				if e.Go {
150					m.ok++
151				} else {
152					m.bad++
153				}
154				m.lines = append(m.lines, stationLine(e, e.T-m.startEpoch)...)
155				m.running = ""
156			case "end":
157				m.ended = true
158			}
159		}
160	}
161	
162	func (m *model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
163		switch msg := msg.(type) {
164		case tea.WindowSizeMsg:
165			m.w, m.h = msg.Width, msg.Height
166		case tea.KeyMsg:
167			switch msg.String() {
168			case "ctrl+c":
169				return m, tea.Quit
170			case " ", "enter":
171				if m.ended || m.launchErr != nil {
172					return m, tea.Quit
173				}
174			}
175		case launchDone:
176			m.readEvents()
177			if !m.ended {
178				m.launchErr = msg.err
179				if m.launchErr == nil {
180					m.launchErr = fmt.Errorf("the launch ended without its last event")
181				}
182			}
183		case tickMsg:
184			m.frame++
185			if m.earlyShown < len(early) && m.frame%2 == 0 {
186				e := early[m.earlyShown]
187				if e[0] == "" { // the wake-up lines: green, no hook word
188					m.lines = append(m.lines, fmt.Sprintf("%s %s", stamp(0.12*float64(m.earlyShown+1)), sOK.Render(e[1])))
189				} else {
190					m.lines = append(m.lines, fmt.Sprintf("%s %s %s", stamp(0.12*float64(m.earlyShown+1)), sAcc.Render(e[0]), sFg.Render(e[1])))
191				}
192				m.earlyShown++
193				if m.earlyShown == len(early) {
194					m.lines = append(m.lines, "")
195				}
196			} else if m.earlyShown == len(early) {
197				m.readEvents()
198			}
199			return m, tick()
200		}
201		return m, nil
202	}
203	
204	func (m *model) hero(still bool) string {
205		shown := -1
206		if !still {
207			shown = 2 + m.frame/2 // the panel types in, two ticks a line
208		}
209		logo := m.spin.frame(time.Now(), still)
210		return lipgloss.JoinHorizontal(lipgloss.Center, logo, "    ", fetchBlock(m.fetch, shown))
211	}
212	
213	func banner() string {
214		return sAccB.Render("        B  O  L  D  V  E  N  T  U  R  E") + "\n" +
215			sDim.Render("   ── the Command · launch sequence "+strings.Repeat("─", 22))
216	}
217	
218	func (m *model) tail() []string {
219		out := append([]string{}, m.lines...)
220		if m.running != "" {
221			n := int(time.Since(m.runSince).Milliseconds()/80) % 30
222			spin := string("|/-\\"[m.frame%4])
223			out = append(out, fmt.Sprintf("%s %s %s %s", stamp(float64(time.Now().UnixNano())/1e9-m.startEpoch),
224				sAmber.Render("[  "+spin+"   ]"), sWhite.Render(pad(m.running, 10)), sDim.Render(strings.Repeat(".", n+1))))
225		}
