307	PAGE = r'''<!doctype html>
308	<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
309	<title>The Console</title>
310	<link rel="icon" type="image/svg+xml" href="/favicon.svg">
311	<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&display=swap" rel="stylesheet">
312	<style>
313	/* the boot screen's look, everywhere (Chief 10/18): black ground, BoldVenture orange, mono, box lines, [  OK  ] tags */
314	:root{--bg:#050608;--fg:#c6cbc8;--dim:#5f6160;--acc:#FF5A1F;--accd:#6e280e;--accm:#be4216;--acch:#FFB08F;--ok:#4ec96f;--bad:#e5604d;--am:#e3b341;--hl:#10151b}
315	*{box-sizing:border-box}
316	html,body{margin:0;height:100%;background:var(--bg);color:var(--fg);font:13px/1.45 "IBM Plex Mono",Consolas,monospace}
317	body{display:grid;grid-template-rows:auto 1fr auto auto;padding:8px 12px;gap:6px;height:100vh;overflow:hidden}
318	.top{display:flex;justify-content:space-between;color:var(--dim);white-space:pre;overflow:hidden}
319	.top b{color:var(--acc)}
320	main{display:grid;grid-template-columns:250px 1fr;gap:8px;min-height:0}
321	.col{display:grid;grid-template-rows:auto 1fr;gap:16px;min-height:0;padding-top:.8em}
322	.box{position:relative;border:1px solid var(--dim);padding:14px 8px 8px;min-height:0;display:flex;flex-direction:column}
323	/* the label rides on the border, so the box itself never clips; the rail inside it scrolls (Chief 10/18: the cut-off labels) */
324	.box::before{content:"\2524 " attr(data-t) " \251C";position:absolute;top:-.8em;left:10px;background:var(--bg);padding:0 4px;color:var(--dim)}
325	.box.on{border-color:var(--acc)}.box.on::before{color:var(--acc)}
326	#main{padding:12px 0 0;flex-direction:row;margin-top:.8em}
327	.rail{flex:1;min-height:0;overflow:auto}
328	iframe{flex:1;border:0;width:100%;height:100%;background:var(--bg)}
329	.rail div{padding:1px 4px;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
330	.rail div.sel{color:var(--bg);background:var(--acc)}.rail div:not(.sel):hover{background:var(--hl)}
