520	class H(http.server.BaseHTTPRequestHandler):
521	    def log_message(self, *a):
522	        pass
523	
524	    def _send(self, code, body, ctype):
525	        if isinstance(body, str):
526	            body = body.encode("utf-8")
527	        self.send_response(code)
528	        self.send_header("Content-Type", ctype)
529	        self.send_header("Content-Length", str(len(body)))
530	        self.send_header("Cache-Control", "no-store")
531	        self.end_headers()
532	        self.wfile.write(body)
533	
534	    def do_GET(self):
535	        from urllib.parse import unquote
536	        path = unquote(self.path.split("?")[0])
537	        if path == "/":
538	            return self._send(200, PAGE, "text/html; charset=utf-8")
539	        if path in ("/favicon.svg", "/favicon.ico") and os.path.isfile(MARK):   # the BoldVenture bunny bandit (Chief 10/18)
540	            with open(MARK, "rb") as fh:
541	                return self._send(200, fh.read(), "image/svg+xml")
542	        if path == "/panes.json":
543	            return self._send(200, json.dumps({"panes": PANES, "aliases": aliases()}), "application/json; charset=utf-8")
544	        if path == "/glasses.json":
545	            return self._send(200, json.dumps({"glasses": read_glasses()}, ensure_ascii=False), "application/json; charset=utf-8")
546	        if path == "/boot.json":
547	            b = read_boot()
548	            b["fetch"] = fetch_info()
549	            return self._send(200, json.dumps(b, ensure_ascii=False), "application/json; charset=utf-8")
550	        if path == "/status.json":
551	            return self._send(200, json.dumps({"pull": read_status()}), "application/json; charset=utf-8")
552	        if path == "/show.json":
553	            with SHOW_LOCK:
554	                s = {"seq": SHOW["seq"], "url": SHOW["url"], "title": SHOW["title"]}
555	            return self._send(200, json.dumps(s, ensure_ascii=False), "application/json; charset=utf-8")
556	        if path.startswith("/local/"):
557	            f = LOCAL.get(path[7:])
558	            if f and os.path.isfile(f):
559	                return self._send(200, page_bytes(f, "local-" + path[7:]), "text/html; charset=utf-8")
560	        if path.startswith("/store/"):   # the db stand-in: GET /store/<key>/<collection> -> {doc id: data}
561	            parts = path[7:].split("/")
562	            if len(parts) == 2:
563	                with STORE_LOCK:
564	                    data = store_read(parts[0]).get("collections", {}).get(parts[1], {})
565	                return self._send(200, json.dumps(data, ensure_ascii=False), "application/json; charset=utf-8")
566	        if path.startswith("/glass/"):   # /glass/<id>/<file>: only files a publish named, and their own folder's assets
567	            parts = path[7:].split("/", 1)
568	            g = next((x for x in read_glasses() if x.get("id") == parts[0] and x.get("local")), None)
569	            if g and len(parts) == 2:
570	                base = os.path.dirname(os.path.abspath(g["file"]))
571	                f = os.path.abspath(os.path.join(base, parts[1]))
572	                if f.startswith(base + os.sep) and os.path.isfile(f):
573	                    ctype = mimetypes.guess_type(f)[0] or "application/octet-stream"
574	                    if ctype.startswith("text/") or ctype.endswith(("json", "javascript")):
575	                        ctype += "; charset=utf-8"
576	                    return self._send(200, page_bytes(f, g["id"]), ctype)
577	        self._send(404, "not found", "text/plain")
578	
579	    def _store(self, method):
580	        """the db stand-in's writes: PUT sets a doc, PATCH merges into it, DELETE removes it"""
581	        from urllib.parse import unquote
582	        parts = [unquote(p) for p in self.path.split("?")[0][7:].split("/")]
583	        if not self.path.startswith("/store/") or len(parts) != 3:
