"""Round 2 (10/31): close LuaTools, move its Steam hooks into the holding folder (nothing deleted), start Steam clean."""
import os, shutil, subprocess, time

STEAM = "C:/Program Files (x86)/Steam"
HOLD = "H:/SteamLibrary/_crack-removed/steam-root-2"
FILES = ["OpenSteamTool.dll", "winmm.dll", "winmm_real.dll", "dwmapi.dll", "xinput1_4.dll"]

for im in ("LuaTools.exe", "steamerrorreporter64.exe", "steamerrorreporter.exe", "steamwebhelper.exe", "steam.exe"):
    r = subprocess.run(["taskkill", "/F", "/IM", im], capture_output=True, text=True)
    if r.returncode == 0:
        print("closed:", im)
time.sleep(3)
os.makedirs(HOLD, exist_ok=True)
moves = [(f"{STEAM}/{f}", f"{HOLD}/{f}") for f in FILES]
if os.path.isdir(f"{STEAM}/config/stplug-in"):
    moves.append((f"{STEAM}/config/stplug-in", f"{HOLD}/stplug-in"))
for src, dst in moves:
    if not os.path.exists(src):
        print("not there:", src); continue
    for _ in range(20):
        try:
            shutil.move(src, dst); print("moved:", src); break
        except PermissionError:
            time.sleep(1)
    else:
        print("STILL LOCKED:", src)
crash = f"{STEAM}/.crash"
if os.path.exists(crash):
    os.remove(crash)
subprocess.Popen(["cmd", "/c", "start", "", f"{STEAM}/steam.exe".replace("/", "\\")], close_fds=True)
time.sleep(35)
out = subprocess.run(["tasklist", "/FO", "CSV", "/NH"], capture_output=True, text=True).stdout.lower()
print("steam.exe running:", '"steam.exe"' in out, "· webhelper:", "steamwebhelper.exe" in out,
      "· error reporter:", "steamerrorreporter" in out, "· luatools:", "luatools.exe" in out)

